WITH s AS (
  UPDATE sessions SET actions_used = actions_used + 1 WHERE session_id = $1 RETURNING actions_used
), t AS (
  INSERT INTO case_interactions (session_id, case_id, turn_index, agent, player_message, agent_reply)
  VALUES ($1, $2, (SELECT COALESCE(MAX(turn_index), 0) + 1 FROM case_interactions WHERE session_id = $1),
          $3, $4, $5::jsonb)
  RETURNING id
)
SELECT t.id AS turn_id, s.actions_used FROM s, t;

