# Minimal JSON helpers: n8n's Python task runner blocks stdlib imports (incl. json) by default.
def to_json(v):
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, (int, float)):
        return str(v)
    if isinstance(v, str):
        out = '"'
        for ch in v:
            code = ord(ch)
            if ch == '"' or ch == "\\":
                out += "\\" + ch
            elif ch == "\n":
                out += "\\n"
            elif ch == "\r":
                out += "\\r"
            elif ch == "\t":
                out += "\\t"
            elif code < 32 or 126 < code < 0x10000:
                out += "\\u%04x" % code
            elif code >= 0x10000:
                code -= 0x10000
                out += "\\u%04x\\u%04x" % (0xD800 + (code >> 10), 0xDC00 + (code & 0x3FF))
            else:
                out += ch
        return out + '"'
    if isinstance(v, (list, tuple)):
        return "[" + ",".join(to_json(x) for x in v) + "]"
    if isinstance(v, dict):
        return "{" + ",".join(to_json(str(k)) + ":" + to_json(x) for k, x in v.items()) + "}"
    return to_json(str(v))

def parse_json(s):
    pos = [0]
    n = len(s)
    escapes = {'"': '"', "\\": "\\", "/": "/", "b": "\b", "f": "\f", "n": "\n", "r": "\r", "t": "\t"}

    def ws():
        while pos[0] < n and s[pos[0]] in " \t\r\n":
            pos[0] += 1

    def expect(ch):
        ws()
        if pos[0] >= n or s[pos[0]] != ch:
            raise ValueError("expected " + ch)
        pos[0] += 1

    def peek():
        ws()
        return s[pos[0]] if pos[0] < n else ""

    def value():
        c = peek()
        if c == "{":
            pos[0] += 1
            out = {}
            if peek() == "}":
                pos[0] += 1
                return out
            while True:
                if peek() != '"':
                    raise ValueError("expected key")
                key = value()
                expect(":")
                out[key] = value()
                if peek() == ",":
                    pos[0] += 1
                    continue
                expect("}")
                return out
        if c == "[":
            pos[0] += 1
            out = []
            if peek() == "]":
                pos[0] += 1
                return out
            while True:
                out.append(value())
                if peek() == ",":
                    pos[0] += 1
                    continue
                expect("]")
                return out
        if c == '"':
            pos[0] += 1
            out = ""
            while True:
                if pos[0] >= n:
                    raise ValueError("unterminated string")
                ch = s[pos[0]]
                pos[0] += 1
                if ch == '"':
                    return out
                if ch != "\\":
                    out += ch
                    continue
                esc = s[pos[0]:pos[0] + 1]
                pos[0] += 1
                if esc == "u":
                    code = int(s[pos[0]:pos[0] + 4], 16)
                    pos[0] += 4
                    if 0xD800 <= code < 0xDC00 and s[pos[0]:pos[0] + 2] == "\\u":
                        low = int(s[pos[0] + 2:pos[0] + 6], 16)
                        if 0xDC00 <= low < 0xE000:
                            code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
                            pos[0] += 6
                    out += chr(code)
                elif esc in escapes:
                    out += escapes[esc]
                else:
                    raise ValueError("bad escape")
        for word, val in (("true", True), ("false", False), ("null", None)):
            if s.startswith(word, pos[0]):
                pos[0] += len(word)
                return val
        start = pos[0]
        while pos[0] < n and s[pos[0]] in "+-0123456789.eE":
            pos[0] += 1
        text = s[start:pos[0]]
        if not text:
            raise ValueError("unexpected character")
