    result = value()
    ws()
    if pos[0] != n:
        raise ValueError("trailing data")
    return result

def dump(obj):
    return to_json(obj)

STUB = {
    "case_starry_night": [{"material": "cobalt_blue", "confidence": 0.91}, {"material": "synthetic_ultramarine", "confidence": 0.07}],
