        if not text:
            raise ValueError("unexpected character")
        return float(text) if ("." in text or "e" in text or "E" in text) else int(text)

    result = value()
    ws()
    if pos[0] != n:
        raise ValueError("trailing data")
    return result

def dump(obj):
    return to_json(obj)

def year(x):
    return int(x) if x == int(x) else x

data = _query
if isinstance(data, str):
    try:
        data = parse_json(data)
    except Exception:
        return dump({"error": 'Input must be a JSON object of named windows, e.g. {"material":[1907,2026],"claimed":[1650,1700]}'})
if isinstance(data, dict) and isinstance(data.get("input"), str):
    try:
        data = parse_json(data["input"])
    except Exception:
