windows = []
for name, w in (data.items() if isinstance(data, dict) else []):
    try:
        if not isinstance(w, list) or len(w) != 2:
            raise ValueError
        start, end = float(w[0]), float(w[1])
        if start != start or end != end:
            raise ValueError
    except (ValueError, TypeError):
        return dump({"error": 'Window "' + str(name) + '" must be [start, end] numbers'})
    windows.append({"name": name, "start": year(start), "end": year(end)})
if len(windows) < 2:
    return dump({"error": "Need at least two named windows"})

# a = window with the latest start, b = window with the earliest end
a = b = windows[0]
for w in windows:
    if w["start"] > a["start"]:
        a = w
    if w["end"] < b["end"]:
        b = w
if a["start"] <= b["end"]:
    return dump({"empty": False, "interval": [a["start"], b["end"]]})
return dump({"empty": True, "conflicting_pair": [a["name"], b["name"]], "gap_years": a["start"] - b["end"]})

